import pytest


def accepted(cap: int, xs: list[int]) -> int:
    """Return how many items of xs are accepted by a bounded queue.

    The queue holds at most ``cap`` integers (``cap`` >= 0). Each element of
    ``xs`` is offered in order with a non-blocking put. Acceptance stops at the
    first put that finds the queue full, and the number of accepted puts up to
    that point is returned. With ``cap == 0`` nothing is accepted.
    """
    queue: list[int] = []
    count = 0
    for x in xs:
        if len(queue) >= cap:
            break
        queue.append(x)
        count += 1
    return count


def test_accepted_stops_when_full() -> None:
    assert accepted(2, [1, 2, 3]) == 2


def test_accepted_all_fit() -> None:
    assert accepted(5, [1, 2]) == 2


def test_accepted_empty_input() -> None:
    assert accepted(3, []) == 0


def test_accepted_zero_capacity() -> None:
    assert accepted(0, [1, 2, 3]) == 0


def test_accepted_exact_capacity() -> None:
    assert accepted(3, [7, 8, 9]) == 3
